+import { createEventCard } from './event-card.js';
+
+export function sortChronologically(events, build = createEventCard) {
+  return events
+    .map((event, index) => ({ value: build(event), time: new Date(event.startsAt).getTime(), index }))
+    .sort((a, b) => a.time - b.time || a.index - b.index)
+    .map(({ value }) => value);
+}
+
+export function buildAgenda(events) {
+  return sortChronologically(events);
+}

